practice.solution:
const laps = [62, 58, 65, 57, 60];

laps.forEach((seconds, index) => {
  console.log(`Lap ${index + 1}: ${seconds}s`);
});

let fastest = Infinity;
let fastestLap = 0;
laps.forEach((seconds, index) => {
  if (seconds < fastest) {
    fastest = seconds;
    fastestLap = index + 1;
  }
});

console.log(`Fastest: Lap ${fastestLap} (${fastest}s)`);

for (const [i, seconds] of laps.entries()) {
  if (seconds < 60) {
    console.log(`First under 60s: Lap ${i + 1}`);
    break;
  }
}
